#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(i32)]
pub enum ETresDamageAttribute {
    Physical = 0,
    Fire = 1,
    Blizzard = 2,
    Thunder = 3,
    Water = 4,
    Aero = 5,
    Dark = 6,
    Notype = 7,
    Max = 8,
}

impl ETresDamageAttribute {
    pub const ALL: &'static [ETresDamageAttribute] = &[ETresDamageAttribute::Physical, ETresDamageAttribute::Fire, ETresDamageAttribute::Blizzard, ETresDamageAttribute::Thunder, ETresDamageAttribute::Water, ETresDamageAttribute::Aero, ETresDamageAttribute::Dark, ETresDamageAttribute::Notype, ETresDamageAttribute::Max];
    pub const fn name(self) -> &'static str {
        match self {
            ETresDamageAttribute::Physical => "Physical",
            ETresDamageAttribute::Fire => "Fire",
            ETresDamageAttribute::Blizzard => "Blizzard",
            ETresDamageAttribute::Thunder => "Thunder",
            ETresDamageAttribute::Water => "Water",
            ETresDamageAttribute::Aero => "Aero",
            ETresDamageAttribute::Dark => "Dark",
            ETresDamageAttribute::Notype => "Notype",
            ETresDamageAttribute::Max => "Max",
        }
    }
    pub const fn game_name(self) -> &'static str {
        match self {
            ETresDamageAttribute::Physical => "TRES_DMG_ATTR_PHYSICAL",
            ETresDamageAttribute::Fire => "TRES_DMG_ATTR_FIRE",
            ETresDamageAttribute::Blizzard => "TRES_DMG_ATTR_BLIZZARD",
            ETresDamageAttribute::Thunder => "TRES_DMG_ATTR_THUNDER",
            ETresDamageAttribute::Water => "TRES_DMG_ATTR_WATER",
            ETresDamageAttribute::Aero => "TRES_DMG_ATTR_AERO",
            ETresDamageAttribute::Dark => "TRES_DMG_ATTR_DARK",
            ETresDamageAttribute::Notype => "TRES_DMG_ATTR_NOTYPE",
            ETresDamageAttribute::Max => "TRES_DMG_ATTR_MAX",
        }
    }
    pub const fn value(self) -> i32 {
        self as i32
    }
    pub const fn from_value(value: i32) -> Option<ETresDamageAttribute> {
        match value {
            0 => Some(ETresDamageAttribute::Physical),
            1 => Some(ETresDamageAttribute::Fire),
            2 => Some(ETresDamageAttribute::Blizzard),
            3 => Some(ETresDamageAttribute::Thunder),
            4 => Some(ETresDamageAttribute::Water),
            5 => Some(ETresDamageAttribute::Aero),
            6 => Some(ETresDamageAttribute::Dark),
            7 => Some(ETresDamageAttribute::Notype),
            8 => Some(ETresDamageAttribute::Max),
            _ => None,
        }
    }
    pub fn from_game_name(name: &str) -> Option<ETresDamageAttribute> {
        let name = name.rsplit("::").next().unwrap_or(name);
        match name {
            "TRES_DMG_ATTR_PHYSICAL" => Some(ETresDamageAttribute::Physical),
            "PHYSICAL" => Some(ETresDamageAttribute::Physical),
            "TRES_DMG_ATTR_FIRE" => Some(ETresDamageAttribute::Fire),
            "FIRE" => Some(ETresDamageAttribute::Fire),
            "TRES_DMG_ATTR_BLIZZARD" => Some(ETresDamageAttribute::Blizzard),
            "BLIZZARD" => Some(ETresDamageAttribute::Blizzard),
            "TRES_DMG_ATTR_THUNDER" => Some(ETresDamageAttribute::Thunder),
            "THUNDER" => Some(ETresDamageAttribute::Thunder),
            "TRES_DMG_ATTR_WATER" => Some(ETresDamageAttribute::Water),
            "WATER" => Some(ETresDamageAttribute::Water),
            "TRES_DMG_ATTR_AERO" => Some(ETresDamageAttribute::Aero),
            "AERO" => Some(ETresDamageAttribute::Aero),
            "TRES_DMG_ATTR_DARK" => Some(ETresDamageAttribute::Dark),
            "DARK" => Some(ETresDamageAttribute::Dark),
            "TRES_DMG_ATTR_NOTYPE" => Some(ETresDamageAttribute::Notype),
            "NOTYPE" => Some(ETresDamageAttribute::Notype),
            "TRES_DMG_ATTR_MAX" => Some(ETresDamageAttribute::Max),
            "MAX" => Some(ETresDamageAttribute::Max),
            _ => None,
        }
    }
}
